styles.content:
/* Host je .elastyc-front-auth. Boje idu iz Webfront ili Main tokena; bez njih ostaju sistemske. */

.elastyc-front-auth {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  color: var(--text, var(--main-font-color, CanvasText));
  font: inherit;
  font-size: 14px;
  line-height: 1.4;
}

.elastyc-front-auth *,
.elastyc-front-auth *::before,
.elastyc-front-auth *::after {
  box-sizing: border-box;
}

.elastyc-front-auth .efa-root {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.elastyc-front-auth .efa-title {
  margin: 0 0 12px;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--main-accent-color, inherit);
}

.elastyc-front-auth .efa-lead,
.elastyc-front-auth .efa-or {
  margin: 0 0 12px;
  font-size: 13px;
  color: var(--muted, var(--main-font-color-light, GrayText));
}

.elastyc-front-auth .efa-or {
  text-align: center;
}

.elastyc-front-auth .efa-error {
  margin: 0 0 12px;
  font-size: 13px;
  color: var(--danger, var(--alert-color, Mark));
}

.elastyc-front-auth .efa-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0 0 12px;
}

.elastyc-front-auth .efa-field > span {
  font-size: 12px;
  color: var(--muted, var(--case-label-color, var(--main-font-color-light, GrayText)));
}

.elastyc-front-auth .efa-field input,
.elastyc-front-auth .efa-field select {
  width: 100%;
  min-height: 36px;
  padding: 6px 10px;
  border: 1px solid var(--line, var(--form-input-border-color, ButtonBorder));
  border-radius: 4px;
  background: var(--panel-raised, var(--form-input-background, Field));
  color: var(--text, var(--form-input-font-color, FieldText));
  font: inherit;
}

.elastyc-front-auth .efa-field input:focus-visible,
.elastyc-front-auth .efa-field select:focus-visible {
  outline: 2px solid var(--accent, var(--form-input-border-color-focus, Highlight));
  outline-offset: 2px;
}

.elastyc-front-auth .efa-field input[readonly] {
  opacity: 0.85;
}

.elastyc-front-auth .efa-primary,
.elastyc-front-auth .efa-provider,
.elastyc-front-auth .efa-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 36px;
  margin: 0 0 8px;
  padding: 6px 12px;
  border-radius: 4px;
  font: inherit;
  cursor: pointer;
}

.elastyc-front-auth .efa-primary {
  border: 1px solid transparent;
  background: var(--accent-strong, var(--main-button-background, ButtonFace));
  color: var(--main-button-font-color, ButtonText);
}

.elastyc-front-auth .efa-provider {
  border: 1px solid var(--line, var(--main-boder-color, ButtonBorder));
  background: var(--panel, var(--main-background2, Canvas));
  color: var(--text, var(--main-font-color, ButtonText));
}

.elastyc-front-auth .efa-link {
  border: 0;
  background: transparent;
  color: var(--accent, var(--main-accent-color2, LinkText));
}

.elastyc-front-auth .efa-primary:focus-visible,
.elastyc-front-auth .efa-provider:focus-visible,
.elastyc-front-auth .efa-link:focus-visible {
  outline: 2px solid var(--accent, var(--form-input-border-color-focus, Highlight));
  outline-offset: 2px;
}

.elastyc-front-auth .efa-primary:disabled,
.elastyc-front-auth .efa-provider:disabled,
.elastyc-front-auth .efa-link:disabled {
  cursor: default;
  opacity: 0.6;
}

@media (max-width: 480px) {
  .elastyc-front-auth .efa-primary,
  .elastyc-front-auth .efa-provider {
    min-height: 44px;
  }
}

.elastyc-front-auth {
  max-width: var(--front-auth-width, 480px);
  margin-inline: auto;
  font-family: var(--front-auth-font, inherit);
  font-size: var(--front-auth-size, 14px);
  color: var(--front-auth-text, var(--text, var(--main-font-color, CanvasText)));
}

.elastyc-front-auth .efa-field {
  margin-block-end: var(--front-auth-gap, 12px);
}

.elastyc-front-auth .efa-field input,
.elastyc-front-auth .efa-field select {
  border-color: var(--front-auth-field-border, var(--line, var(--form-input-border-color, ButtonBorder)));
  border-radius: var(--front-auth-radius, 4px);
  background: var(--front-auth-field-bg, var(--panel-raised, var(--form-input-background, Field)));
  color: var(--front-auth-field-text, var(--text, var(--form-input-font-color, FieldText)));
}

.elastyc-front-auth .efa-primary {
  border-radius: var(--front-auth-radius, 4px);
  background: var(--front-auth-button-bg, var(--accent-strong, var(--main-button-background, ButtonFace)));
  color: var(--front-auth-button-text, var(--main-button-font-color, ButtonText));
  text-decoration: none;
}

.elastyc-front-auth .efa-link {
  text-decoration: none;
}

.elastyc-front-auth .efa-link:hover {
  text-decoration: underline;
}

.elastyc-front-auth .efa-brand {
  min-height: 41px;
  gap: 12px;
  border: 1px solid #747775;
  border-radius: 4px;
  background: #fff;
  color: #1f1f1f;
  font: 500 14px/20px "Google Sans", Roboto, Arial, sans-serif;
}

.elastyc-front-auth .efa-brand-microsoft {
  border-color: #8c8c8c;
  color: #5e5e5e;
  font-family: "Segoe UI", Arial, sans-serif;
  font-weight: 600;
}

.elastyc-front-auth .efa-brand img {
  flex: 0 0 18px;
  width: 18px;
  height: 18px;
  max-width: 18px;
  object-fit: contain;
}

.efa-page {
  color-scheme: light dark;
}

.efa-page-body {
  --panel: #fff;
  --panel-raised: #fff;
  --text: #17253a;
  --muted: #536479;
  --line: #c8d2df;
  --accent: #214c96;
  --accent-strong: #214c96;
  --danger: #ae2631;
  --front-auth-button-text: #fff;
  min-height: 100vh;
  display: grid;
  place-items: center;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
  background: #f4f6fa;
  color: var(--text);
  font: 400 15px/1.5 system-ui, sans-serif;
}

.efa-page-panel {
  box-sizing: border-box;
  width: min(100%, 538px);
  padding: clamp(18px, 5vw, 28px);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
}

@media (prefers-color-scheme: dark) {
  .efa-page-body {
    --panel: #142033;
    --panel-raised: #1b2a41;
    --text: #e9effa;
    --muted: #a7b7cd;
    --line: #41546f;
    --accent: #a9c6ff;
    --accent-strong: #aac7ff;
    --danger: #ff9ca5;
    --front-auth-button-text: #142033;
    background: #0d1727;
  }
}
.elastyc-front-auth .efa-registration-company {
  display: block;
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
}
.elastyc-front-auth .efa-registration-company[hidden] { display: none; }
.elastyc-front-auth .efa-registration-company legend { padding: 0; margin: 0 0 12px; font-size: 14px; font-weight: 600; color: inherit; }
.elastyc-front-auth .efa-registration-company .efa-lead:empty { display: none; }
.elastyc-front-auth .efa-registration-consent {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: .875em;
}
.elastyc-front-auth .efa-registration-consent input { width: auto; flex-shrink: 0; margin-top: 4px; }

.elastyc-front-auth .efa-root--account .efa-account-identity {
  display: flex;
  align-items: center;
  gap: .875rem;
}
.elastyc-front-auth .efa-root--account .efa-account-avatar {
  display: grid;
  flex: none;
  place-items: center;
  width: 2.875rem;
  height: 2.875rem;
  border-radius: 50%;
  background: var(--wf-color-background, var(--panel-raised, var(--main-background2, Canvas)));
  background: color-mix(in srgb, var(--wf-color-primary, var(--accent, var(--main-accent-color3, Highlight))) 12%, var(--wf-color-surface, var(--panel, var(--main-background1, Canvas))));
  color: var(--wf-color-primary, var(--accent, var(--main-accent-color3, Highlight)));
  font-weight: 700;
}
.elastyc-front-auth .efa-root--account .efa-account-description {
  min-width: 0;
  overflow-wrap: anywhere;
}
.elastyc-front-auth .efa-root--account .efa-account-name {
  margin: 0;
  color: var(--front-auth-text, var(--wf-color-text, var(--text, var(--main-font-color, CanvasText))));
  font-size: clamp(1.125rem, 5vw, 1.5rem);
  line-height: 1.25;
  font-weight: 700;
}
.elastyc-front-auth .efa-root--account .efa-account-company {
  margin: .25rem 0 0;
  color: var(--wf-color-muted, var(--muted, var(--main-font-color-light, GrayText)));
}
.elastyc-front-auth .efa-root--account > :is(.efa-lead, .efa-error):not([hidden]) {
  margin: .75rem 0 0;
}
.elastyc-front-auth .efa-root--account .efa-account-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem .5rem;
  margin-block-start: 1.25rem;
}
.elastyc-front-auth .efa-root--account .efa-account-actions > button {
  width: auto;
  min-height: 44px;
  margin: 0;
  padding-inline: .875rem;
}
.elastyc-front-auth .efa-root--account .efa-account-actions .efa-link,
.elastyc-front-auth .efa-root--account .efa-connection-status {
  color: var(--wf-color-muted, var(--muted, var(--main-font-color-light, GrayText)));
}
.elastyc-front-auth .efa-root--account .efa-connections {
  margin-block-start: .875rem;
  border-top: 1px solid var(--wf-color-border, var(--line, var(--main-boder-color, ButtonBorder)));
}
.elastyc-front-auth .efa-root--account .efa-connections > summary {
  width: fit-content;
  min-height: 44px;
  padding: .75rem 0;
  line-height: 1.25rem;
  cursor: pointer;
  color: var(--wf-color-muted, var(--muted, var(--main-font-color-light, GrayText)));
  font-weight: 600;
}
.elastyc-front-auth .efa-root--account .efa-connections-list {
  display: grid;
  gap: .5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.elastyc-front-auth .efa-root--account .efa-connections-list > li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: .5rem;
}
.elastyc-front-auth .efa-root--account .efa-connections-list .efa-brand,
.elastyc-front-auth .efa-root--account .efa-connections-list .efa-google-slot { margin: 0; }

.elastyc-front-auth .efa-root--account .efa-connection-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: .25rem .5rem;
}
.elastyc-front-auth .efa-root--account .efa-connection-actions .efa-unlink {
  width: auto;
  min-height: 44px;
  margin: 0;
  padding: 4px 8px;
  color: var(--front-auth-text, var(--wf-color-text, var(--text, var(--main-font-color, CanvasText))));
}

.elastyc-front-auth .efa-error {
  padding: .75rem .875rem;
  border: 1px solid var(--wf-color-border, var(--line, var(--main-boder-color, ButtonBorder)));
  border-inline-start: 3px solid var(--wf-color-primary, var(--accent, var(--main-accent-color3, Highlight)));
  border-radius: 6px;
  background: var(--wf-color-background, var(--panel-raised, var(--main-background2, Canvas)));
  color: var(--front-auth-text, var(--wf-color-text, var(--text, var(--main-font-color, CanvasText))));
  font-size: .875rem;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.elastyc-front-auth .efa-error > strong {
  display: block;
  margin-block-end: .25rem;
  font-weight: 700;
}

.elastyc-front-auth .efa-error .efa-reauthenticate {
  width: auto;
  min-height: 44px;
  margin: .75rem 0 0;
}

.elastyc-front-auth .efa-provider.efa-brand {
  position: relative;
  box-sizing: border-box;
  min-height: 40px;
  padding-inline: 40px;
  border-color: #dadce0;
}
.elastyc-front-auth .efa-provider.efa-brand > img {
  position: absolute;
  inset-inline-start: 12px;
  top: 50%;
  transform: translateY(-50%);
}
.elastyc-front-auth .efa-google-slot {
  width: 100%;
  min-width: 0;
  min-height: 40px;
  margin-block-end: 8px;
}
.elastyc-front-auth .efa-google-slot iframe { display: block; max-width: 100%; }
.wf-front-auth:has([data-efa-view="account"]) > .wf-front-auth__title { display: none; }

.elastyc-front-auth .efa-name-row { display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 3fr); gap: 12px; }
.elastyc-front-auth .efa-name-row > .efa-field { min-width: 0; }
.elastyc-front-auth .iti {
  width: 100%; min-width: 0;
  --iti-country-selector-bg: var(--front-auth-field-bg, var(--panel-raised, Field));
  --iti-border-color: var(--front-auth-field-border, var(--line, ButtonBorder));
  --iti-icon-color: var(--front-auth-field-text, var(--text, FieldText));
  --iti-hover-color: color-mix(in srgb, currentColor 8%, transparent);
}
.elastyc-front-auth .iti button { color: inherit; font: inherit; }
.elastyc-front-auth .iti__country-selector { max-width: 100%; color: var(--front-auth-field-text, var(--text, FieldText)); }
.elastyc-front-auth .iti__selected-country { border: 0; background: transparent; }
.elastyc-front-auth .iti__country-name { color: inherit; }
.elastyc-front-auth .iti__country-list { text-align: start; }
@media (max-width: 480px) { .elastyc-front-auth .efa-name-row { grid-template-columns: minmax(0, 1fr); gap: 0; } }

/* The shop keeps its own brand; the authentication geometry is shared. */
.wf-shop:has(> [data-wf-shared-commerce-account]) {
  width: min(100%, 480px);
  margin-inline: auto;
}
.elastyc-front-auth [hidden] { display: none !important; }
.elastyc-front-auth .efa-loading,
[data-efa-bootstrap] {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 12px 0;
  font-size: 13px;
  color: var(--front-auth-text, var(--text, var(--main-font-color, CanvasText)));
}
.elastyc-front-auth .efa-loading::before,
[data-efa-bootstrap]::before {
  content: '';
  flex: 0 0 16px;
  width: 16px;
  height: 16px;
  border: 2px solid currentColor;
  border-inline-end-color: transparent;
  border-radius: 50%;
  animation: efa-loading-spin .75s linear infinite;
}
@keyframes efa-loading-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
  .elastyc-front-auth .efa-loading::before,
  [data-efa-bootstrap]::before { animation: none; }
}

.wf-shop,.wf-shop-actions,.wf-shop-shell{--shop-accent:var(--wf-color-primary,#ff9800);--shop-text:var(--wf-color-text,#222526);--shop-muted:var(--wf-color-muted,#626a70);--shop-border:var(--wf-color-border,#e0e4e7);--shop-surface:var(--wf-color-surface,#fff);color:var(--shop-text);font-family:inherit;box-sizing:border-box}
.wf-shop *,.wf-shop-actions *,.wf-shop-shell *{box-sizing:border-box}
.wf-shop{max-width:1160px;padding:32px 24px 64px;margin:0 auto;min-height:45vh}
.wf-shop h1{font-size:clamp(26px,4vw,36px);line-height:1.15;margin:0 0 24px;font-weight:800;letter-spacing:-.025em}
.wf-shop h2{font-size:21px;margin:24px 0 16px}.wf-shop [hidden],.wf-shop-actions [hidden],.wf-shop-shell [hidden]{display:none!important}
.wf-shop-btn,.wf-shop-heart,.wf-shop-link{font:inherit;cursor:pointer;min-height:42px;border-radius:8px;transition:background-color .15s}
.wf-shop-btn{display:inline-flex;align-items:center;justify-content:center;padding:10px 17px;font-weight:750;text-decoration:none;background:var(--shop-accent);border:1px solid transparent;color:var(--wf-shop-on-accent,#171a1c);line-height:1.3}
.wf-shop-btn:hover{filter:brightness(.96)}.wf-shop-btn:disabled{background:#edf0f2;color:#778189;cursor:default;filter:none}.wf-shop-btn:focus-visible,.wf-shop-heart:focus-visible,.wf-shop input:focus-visible,.wf-shop select:focus-visible,.wf-shop-actions input:focus-visible{outline:2px solid var(--shop-accent);outline-offset:3px}
.wf-shop-link{border:0;background:transparent;color:var(--shop-muted);padding:6px 8px;text-decoration:underline;text-underline-offset:3px;font-size:13px}
.wf-shop-shell{display:flex;align-items:center;gap:5px}.wf-shop-shell a{display:inline-flex;align-items:center;gap:6px;padding:9px;color:inherit;text-decoration:none;border-radius:8px;min-height:42px;white-space:nowrap}.wf-shop-shell a:hover{background:var(--wf-color-secondary,#f4f5f6)}
.wf-shop-shell svg,.wf-shop-heart svg{width:21px;height:21px;flex:none}.wf-shop-shell [data-wf-cart-count]{font-size:11px;line-height:18px;min-width:18px;text-align:center;background:var(--shop-text);color:var(--shop-surface);border-radius:9px;font-variant-numeric:tabular-nums}
.wf-shop-actions{padding:10px 12px 12px;border-top:1px solid var(--shop-border);min-height:65px}.wf-detail [data-wf-shop-actions]{padding:16px 0;margin-top:12px}.wf-shop-actions__row{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.wf-shop-actions .wf-shop-btn{flex:1;font-size:13px;padding:9px 10px;min-width:115px}.wf-shop-qty{width:62px;min-width:0;min-height:42px;border:1px solid var(--shop-border);border-radius:8px;background:var(--shop-surface);color:var(--shop-text);font:inherit;padding:8px 5px;text-align:center;font-variant-numeric:tabular-nums}.wf-shop-unit{font-size:12px;color:var(--shop-muted)}
.wf-shop-actions[data-wf-variants=true]{min-height:115px}.wf-product:has(.wf-shop-actions)>.wf-product__link{height:auto;flex:1}
.wf-product:has(.wf-shop-actions){position:relative}.wf-product .wf-shop-heart{position:absolute;top:10px;right:10px;z-index:2;box-shadow:0 1px 4px #0001}.wf-catalog[data-badge-position=top-end] .wf-product .wf-shop-heart{left:10px;right:auto}.wf-shop-actions .wf-shop-qty{width:56px}.wf-product .wf-shop-btn{min-width:105px;font-size:12px}.wf-shop-unit{white-space:nowrap}
.wf-shop-heart{display:inline-flex;align-items:center;justify-content:center;flex:none;width:42px;border:1px solid var(--shop-border);background:var(--shop-surface);color:var(--shop-muted)}.wf-shop-heart[aria-pressed=true]{color:#b52737;background:#fff5f6}.wf-shop-heart[aria-pressed=true] svg{fill:currentColor}
.wf-shop-variant{width:100%;margin-bottom:8px;padding:10px;border:1px solid var(--shop-border);border-radius:8px;font:inherit;background:var(--shop-surface);color:var(--shop-text)}
.wf-shop-lines{border-top:1px solid var(--shop-border);margin-bottom:24px}.wf-shop-line{display:flex;align-items:center;gap:18px;padding:20px 0;border-bottom:1px solid var(--shop-border);min-width:0}.wf-shop-line img{width:88px;height:88px;object-fit:cover;border-radius:10px;background:#f5f6f7}.wf-shop-line__body{display:flex;flex:1;flex-direction:column;gap:7px;min-width:0}.wf-shop-line a{color:var(--shop-text);font-weight:750;text-decoration:none}.wf-shop-line a:hover{text-decoration:underline}.wf-shop-line small{color:var(--shop-muted);font-size:12px}.wf-shop-line__controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.wf-shop-line__controls strong{display:block;min-width:100px;text-align:right;font-variant-numeric:tabular-nums}.wf-shop-line__controls .wf-shop-qty{width:78px}
.wf-shop-totals{width:min(100%,370px);margin-left:auto;border-top:1px solid var(--shop-border);padding-top:12px}.wf-shop-totals>div{display:flex;justify-content:space-between;gap:20px;padding:7px 0;font-variant-numeric:tabular-nums}.wf-shop-totals>div:last-child{font-size:21px;font-weight:800;padding-top:16px;border-top:1px solid var(--shop-border);margin-top:6px}.wf-shop-help{font-size:13px;color:var(--shop-muted);line-height:1.5}.wf-shop-empty{padding:32px 0;color:var(--shop-muted)}
.wf-shop-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;max-width:800px}.wf-shop-field{display:flex;flex-direction:column;gap:7px;font-size:13px;color:var(--shop-muted)}.wf-shop-field input,.wf-shop-field select,.wf-shop-field textarea{width:100%;min-height:44px;border:1px solid var(--shop-border);border-radius:8px;background:var(--shop-surface);color:var(--shop-text);font:inherit;font-size:15px;padding:10px 12px}.wf-shop-field:has(textarea),.wf-shop-form>.wf-shop-btn,.wf-shop-form>.wf-shop-error{grid-column:1/-1}.wf-shop-field textarea{min-height:96px;resize:vertical}.wf-shop-address{grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.wf-shop-form>.wf-shop-btn{justify-self:start}.wf-shop-error{color:#a12626;font-size:14px;margin:0}.wf-shop-error:empty{display:none}.wf-shop-preview{background:#fff8ea;border:1px solid #f0d49e;color:#694711;padding:12px 16px;border-radius:8px;font-size:14px;line-height:1.5}.wf-shop-review{max-width:900px}.wf-shop-notice{position:fixed;z-index:10000;bottom:24px;left:50%;transform:translateX(-50%);max-width:calc(100% - 32px);background:#23312a;color:#fff;border-radius:10px;padding:13px 20px;box-shadow:0 4px 20px #0002;font:14px/1.5 system-ui}.wf-shop-notice:empty{display:none}.wf-shop-notice[data-error=true]{background:#852e2e}
.wf-shop-protection{grid-column:1/-1;min-width:0;max-width:100%}.wf-shop-protection__widget{min-height:65px;max-width:100%;overflow:auto}.wf-shop-protection .wf-shop-help{margin:8px 0 0}.wf-shop-protection .wf-shop-link{padding-left:0}
@media(max-width:700px){.wf-shop{padding:24px 16px 48px}.wf-shop-line{gap:12px;flex-wrap:wrap}.wf-shop-line img{width:65px;height:65px}.wf-shop-line__controls{width:100%;justify-content:flex-start;padding-left:77px}.wf-shop-line__controls strong{margin-left:auto}.wf-shop-form,.wf-shop-address{grid-template-columns:1fr}.wf-shop-form>.wf-shop-btn{width:100%}.wf-shop-shell a{padding:7px}.wf-shop-shell [data-wf-cart-label]{display:none}.wf-shop-actions{padding:10px}.wf-shop-actions .wf-shop-btn{min-width:120px}.wf-shop-notice{bottom:16px;width:max-content}}
@media(prefers-reduced-motion:reduce){.wf-shop-btn,.wf-shop-heart,.wf-shop-link{transition:none}}
.wf-shop-steps{display:flex;gap:8px;margin-bottom:24px;flex-wrap:wrap}.wf-shop-step{font:inherit;text-align:left;border:1px solid var(--shop-border);background:var(--shop-surface);color:var(--shop-muted);padding:12px 16px;border-radius:8px;cursor:pointer;flex:1;min-width:160px}.wf-shop-step[aria-current=step]{color:var(--shop-text);border-color:var(--shop-accent);font-weight:700}.wf-shop-step:disabled{cursor:default;opacity:.6}.wf-shop-step:focus-visible{outline:2px solid var(--shop-accent);outline-offset:3px}.wf-shop-step-panel{grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;min-width:0}.wf-shop-step-panel>h2,.wf-shop-step-panel>.wf-shop-help,.wf-shop-step-panel>.wf-shop-link{grid-column:1/-1}.wf-shop-step-panel>h2{margin:0 0 8px}.wf-shop-step-actions{grid-column:1/-1;display:flex;align-items:center;gap:16px;justify-content:space-between}.wf-shop-step-actions>.wf-shop-btn{margin-left:auto}.wf-shop-confirmation-details{padding:12px 0;border-top:1px solid var(--shop-border);font-size:14px}.wf-shop-confirmation-details p{margin:6px 0}
@media(max-width:700px){.wf-shop-step{min-width:0;flex-basis:100%;padding:10px 12px}.wf-shop-step-panel{grid-template-columns:1fr}.wf-shop-step-actions{gap:8px}.wf-shop-step-actions>.wf-shop-btn{flex:1}}

.wf-shop-protection--quiet .wf-shop-protection__widget{min-height:0}.wf-shop-form[data-inquiry=true] .wf-shop-step-actions>.wf-shop-btn{margin-left:0}

/* Country picker shares the public site's form palette and input geometry. */
.wf-shop-field input::placeholder,.wf-shop-field textarea::placeholder{color:var(--wf-color-placeholder,var(--shop-muted));opacity:.8;font-weight:400;font-size:.94em}
.wf-shop-field .iti{width:100%;min-width:0;--iti-border-color:var(--shop-border);--iti-country-selector-bg:var(--shop-surface);--iti-icon-color:var(--shop-muted);--iti-hover-color:var(--wf-color-secondary,#f4f5f6);--iti-spacer-horizontal:12px}
.wf-shop-field .iti__selected-country{border-radius:8px 0 0 8px;font:inherit;color:var(--shop-text);min-height:44px}
.wf-shop-field .iti__selected-country:focus-visible{outline:2px solid var(--shop-accent);outline-offset:3px}
.wf-shop-field .iti__country-selector{z-index:20;font-size:14px;max-width:calc(100vw - 32px);color:var(--shop-text)}
.wf-shop-field .iti__search-input{padding-left:32px;font-size:14px}
.wf-shop-field>.wf-shop-help:empty{display:none}.wf-shop-field>.wf-shop-help{margin:0}.wf-shop-field>.wf-shop-link{align-self:flex-start;padding:0;min-height:32px;text-align:left}

scripts.content:
(function (global) {
  'use strict';
  var labels = { firstName: 'Ime', lastName: 'Prezime', email: 'Email adresa', phone: 'Telefon',
    companyName: 'Naziv firme', taxNumber: 'PIB / OIB', address: 'Adresa', postalCode: 'Poštanski broj',
    city: 'Mesto', registrationNumber: 'Matični broj', companyEmail: 'Email firme', companyPhone: 'Telefon firme' };
  function node(tag, attrs, children) {
    var e = document.createElement(tag);
    Object.keys(attrs || {}).forEach(function (key) {
      if (key === 'text') e.textContent = attrs[key];
      else if (key === 'className') e.className = attrs[key];
      else if (attrs[key] !== false && attrs[key] != null) e.setAttribute(key, attrs[key] === true ? '' : attrs[key]);
    });
    (children || []).forEach(function (child) { e.appendChild(child); }); return e;
  }
  function randomKey() {
    return Array.from(global.crypto.getRandomValues(new Uint8Array(32))).map(function (n) { return n.toString(16).padStart(2, '0'); }).join('');
  }
  function post(url, data, signal) {
    return fetch(url, { method: 'POST', credentials: 'same-origin', signal: signal, headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify(data) })
      .then(function (response) { return response.json().catch(function () { return { ok: false, message: 'Registracija trenutno nije dostupna.' }; }).then(function (result) {
        if (!response.ok || !result.ok) { var error = new Error(result.message || 'Zahtev trenutno nije dostupan.'); error.status = response.status; throw error; } return result;
      }); });
  }
  var phoneLoader;
  function loadPhone() {
    if (global.intlTelInput && global.intlTelInput.utils) return Promise.resolve(global.intlTelInput);
    if (phoneLoader) return phoneLoader;
    phoneLoader = new Promise(function (resolve, reject) {
      var script = node('script', { src: '/common/intl-tel-input/dist/js/intlTelInputWithUtils.min.js?v=29.1.2' });
      var timer = global.setTimeout(failed, 15000);
      function failed() { global.clearTimeout(timer); script.remove(); phoneLoader = null; reject(new Error('Provera telefona trenutno nije dostupna. Pokušajte ponovo.')); }
      if (!document.getElementById('elastyc-intl-tel-css')) document.head.appendChild(node('link', {
        id: 'elastyc-intl-tel-css', rel: 'stylesheet', href: '/common/intl-tel-input/dist/css/intlTelInput.min.css?v=29.1.2'
      }));
      script.onload = function () {
        if (!global.intlTelInput || !global.intlTelInput.utils) { failed(); return; }
        global.clearTimeout(timer); resolve(global.intlTelInput);
      };
      script.onerror = failed; document.head.appendChild(script);
    });
    return phoneLoader;
  }
  function phoneControl(input, country, notify) {
    var active = true, widget = null, observer = null, unavailable = false;
    function fit() {
      if (!active || !widget) return;
      var button = input.parentNode.querySelector('.iti__selected-country');
      if (button) input.style.setProperty('padding-left', (button.offsetWidth + 10) + 'px', 'important');
      var list = input.parentNode.querySelector('.iti__country-selector');
      if (list && input.offsetWidth) list.style.width = input.offsetWidth + 'px';
    }
    function validate() {
      input.setCustomValidity('');
      if (!input.value.trim()) return '';
      if (!widget) return unavailable ? 'Provera telefona trenutno nije dostupna. Ponovo otvorite registraciju.' : 'Sačekajte učitavanje provere telefona.';
      var utils = global.intlTelInput.utils, value = widget.getNumber();
      return value && utils.isValidNumberPrecise(value, null, null) && !utils.getExtension(value, null) ? '' : 'Unesite ispravan broj telefona za izabranu državu.';
    }
    loadPhone().then(function (factory) {
      if (!active) return;
      widget = factory(input, {
        initialCountry: country.toLowerCase(), countryOrder: [country.toLowerCase(), 'rs', 'ba', 'hr', 'me', 'si', 'mk'],
        countrySelectorMode: 'DROPDOWN', countryNameLocale: 'sr-Latn', allowedNumberTypes: null,
        allowNumberExtensions: false, allowPhonewords: false, numberDisplayFormat: 'NATIONAL',
        placeholderNumberPolicy: 'OFF', separateDialCode: true, strictMode: true,
        uiTranslations: { searchPlaceholder: 'Pretraga zemlje', selectedCountryAriaLabel: 'Izaberite zemlju za telefonski broj',
          noCountrySelected: 'Zemlja nije izabrana', countryListAriaLabel: 'Zemlje', clearSearchAriaLabel: 'Očisti pretragu', searchEmptyState: 'Nema rezultata' }
      });
      widget.setDisabled(input.disabled); fit();
      if (global.ResizeObserver) { observer = new global.ResizeObserver(fit); observer.observe(input); }
    }).catch(function (error) { if (active) { unavailable = true; notify(error.message); } });
    input.addEventListener('input', function () { input.setCustomValidity(''); });
    input.addEventListener('blur', function () { input.setCustomValidity(validate()); });
    input.addEventListener('countrychange', function () { input.setCustomValidity(''); fit(); });
    return {
      value: function () { var message = validate(); input.setCustomValidity(message); if (message) throw new Error(message); return input.value.trim() ? widget.getNumber() : ''; },
      setCountry: function (iso) { country = iso; if (widget && !input.value.trim()) { widget.setCountry(iso.toLowerCase()); fit(); } },
      setDisabled: function (value) { if (widget) widget.setDisabled(value); },
      destroy: function () { if (!active) return; active = false; if (observer) observer.disconnect(); if (widget) widget.destroy(); }
    };
  }
  function mount(options) {
    var host = options.host; host.replaceChildren();
    var alive = true, sequence = 0, controls = [], fields = {}, key = randomKey(), registryValues = {};
    var phone = null;
    var lookupTimer = null, lookupDeadline = null, lookupController = null, lookupKey = '';
    function cancelLookup() {
      sequence++; global.clearTimeout(lookupTimer); global.clearTimeout(lookupDeadline); lookupTimer = null; lookupDeadline = null;
      if (lookupController) lookupController.abort(); lookupController = null;
    }
    function destroy() { if (!alive) return; alive = false; cancelLookup(); if (phone) phone.destroy(); host.replaceChildren(); }
    var title = node('h2', { className: 'efa-title', text: options.token ? 'Potvrdite email i postavite lozinku' : 'Registracija' });
    var status = node('p', { className: 'efa-lead', role: 'status', 'aria-live': 'polite', text: options.token
      ? 'Posle potvrde emaila registraciju pregleda operater.' : 'Pošaljite podatke, potvrdite email i sačekajte odobravanje registracije. Obavezna polja su označena zvezdicom.' });
    var error = node('p', { className: 'efa-error', role: 'alert', hidden: true });
    var form = node('form', { className: 'efa-form' });
    var loading = node('p', { className: 'efa-loading', role: 'status', 'aria-live': 'polite', hidden: true, text: 'Slanje podataka…' });
    var base = '/incKomponente/auth/';
    host.append(title, status, error, form, loading);
    function busy(value) { host.setAttribute('aria-busy', String(value)); loading.hidden = !value; controls.forEach(function (c) { c.disabled = value; }); if (phone) phone.setDisabled(value); }
    function fail(e) { if (!alive) return; error.hidden = false; error.textContent = e.message || 'Zahtev trenutno nije dostupan.'; busy(false); }
    function clearError() { error.hidden = true; error.textContent = ''; }
    function input(name, label, required, type, max, container) {
      var control = node('input', { type: type || 'text', name: name, required: required, maxlength: max || 255,
        autocomplete: name === 'email' ? 'email' : name === 'firstName' ? 'given-name' : name === 'lastName' ? 'family-name' : name.indexOf('password') === 0 ? 'new-password' : 'on' });
      var wrap = node(name === 'phone' ? 'div' : 'label', { className: 'efa-field' }, [node('span', { text: label + (required ? ' *' : '') }), control]);
      (container || form).appendChild(wrap); fields[name] = control; controls.push(control); return wrap;
    }
    var submit = node('button', { className: 'efa-primary', type: 'submit', text: options.token ? 'Potvrdi email' : 'Pošalji registraciju' });
    controls.push(submit);
    var back = node('button', { type: 'button', className: 'efa-link', text: 'Nazad na prijavu' });
    back.addEventListener('click', function () { destroy(); options.onBack(); }); controls.push(back);
    if (options.token) {
      input('password', 'Lozinka — najmanje 12 znakova', true, 'password', 128).querySelector('input').minLength = 12;
      input('passwordConfirmation', 'Ponovite lozinku', true, 'password', 128);
      form.appendChild(submit); host.appendChild(back);
      form.addEventListener('submit', function (event) {
        event.preventDefault(); error.hidden = true;
        if (fields.password.value !== fields.passwordConfirmation.value) { fail(new Error('Lozinke se ne podudaraju.')); return; }
        busy(true);
        post(base + 'register-confirm.php', { token: options.token, password: fields.password.value }).then(function (result) {
          if (!alive) return; if (phone) { phone.destroy(); phone = null; } form.remove(); status.textContent = result.message; busy(false); controls = [back];
        }).catch(fail);
      });
      return { destroy: destroy };
    }
    var config = options.config, type = node('select', { name: 'type', 'aria-label': 'Vrsta kupca' }), country = node('select', { name: 'country' });
    config.types.forEach(function (value) { type.appendChild(node('option', { value: value, text: value === 'PL' ? 'Pravno lice' : 'Fizičko lice' })); });
    config.countries.forEach(function (value) { country.appendChild(node('option', { value: value.id, text: value.name })); });
    if (config.countries.some(function (value) { return value.id === config.defaultCountry; })) country.value = config.defaultCountry;
    form.appendChild(node('label', { className: 'efa-field' }, [node('span', { text: 'Vrsta kupca' }), type]));
    controls.push(type, country);
    var names = node('div', { className: 'efa-name-row' }); form.appendChild(names);
    ['firstName','lastName'].forEach(function (name) { input(name, labels[name], true, 'text', 30, names); });
    input('email', labels.email, true, 'email', 100);
    fields.email.inputMode = 'email'; fields.email.autocapitalize = 'none'; fields.email.spellcheck = false;
    function emailValidity() {
      fields.email.value = fields.email.value.trim(); fields.email.setCustomValidity('');
      if (fields.email.value && (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fields.email.value) || fields.email.validity && fields.email.validity.typeMismatch)) {
        fields.email.setCustomValidity('Unesite važeću email adresu, na primer ime@firma.rs.');
      }
    }
    fields.email.addEventListener('input', function () { fields.email.setCustomValidity(''); });
    fields.email.addEventListener('blur', emailValidity);
    input('phone', labels.phone, false, 'tel', 100); fields.phone.autocomplete = 'tel-national';
    phone = phoneControl(fields.phone, country.value, function (message) { fail(new Error(message)); update(); });
    var countryCaption = node('span'), countryValue = config.countries.length === 1
      ? node('span', { text: config.countries[0].name }) : country;
    form.appendChild(node(config.countries.length === 1 ? 'div' : 'label', { className: 'efa-field' }, [countryCaption, countryValue]));
    var company = node('fieldset', { className: 'efa-registration-company' }, [node('legend', { text: 'Podaci firme' })]); form.appendChild(company);
    input('taxNumber', 'PIB', true, 'text', 20, company);
    var lookup = node('button', { className: 'efa-link', type: 'button', text: 'Pokušaj ponovo', hidden: true }); controls.push(lookup); company.appendChild(lookup);
    var registryState = node('p', { className: 'efa-lead', role: 'status', 'aria-live': 'polite' }); company.appendChild(registryState);
    input('companyName', labels.companyName, true, 'text', 255, company);
    var companyDetails = node('p', { className: 'efa-lead', hidden: true }); company.appendChild(companyDetails);
    company.appendChild(node('p', { className: 'efa-lead', text: 'Ostale podatke firme dopunjavamo prilikom odobravanja registracije.' }));
    var consent = node('input', { type: 'checkbox', required: true, name: 'consent' }); controls.push(consent);
    form.appendChild(node('label', { className: 'efa-registration-consent' }, [consent,
      node('span', { text: 'Prihvatam obradu unetih podataka radi registracije i poslovnog odnosa.' })]));
    form.appendChild(submit); host.appendChild(back);
    function update() {
      company.hidden = type.value !== 'PL';
      countryCaption.textContent = company.hidden ? 'Država' : 'Država firme';
      country.setAttribute('aria-label', countryCaption.textContent);
      Array.from(company.querySelectorAll('input')).forEach(function (c) { c.disabled = company.hidden; });
      Object.keys(fields).forEach(function (name) {
        fields[name].required = !fields[name].disabled && (['firstName','lastName','email'].indexOf(name) !== -1
          || type.value === 'PL' && ['taxNumber','companyName'].indexOf(name) !== -1
          || type.value === 'FL' && (config.required.FL || []).indexOf(name) !== -1);
        var caption = name === 'taxNumber' ? (country.value === 'HR' ? 'OIB' : country.value === 'RS' ? 'PIB' : 'Poreski broj') : labels[name];
        fields[name].closest('.efa-field').querySelector('span').textContent = caption + (fields[name].required ? ' *' : '');
        fields[name].setAttribute('aria-label', caption + (fields[name].required ? ' *' : ''));
      });
      fields.taxNumber.pattern = country.value === 'RS' ? '[0-9]{9}' : country.value === 'HR' ? '[0-9]{11}' : '[A-Za-z0-9]{3,20}';
      fields.taxNumber.inputMode = ['RS','HR'].indexOf(country.value) !== -1 ? 'numeric' : 'text';
    }
    function invalidateRegistry() {
      cancelLookup(); lookupKey = ''; clearError(); lookup.disabled = false; lookup.hidden = true;
      registryState.className = 'efa-lead';
      fields.taxNumber.setCustomValidity(''); fields.companyName.readOnly = false;
      if (fields.companyName.value === registryValues.companyName) fields.companyName.value = '';
      companyDetails.textContent = ''; companyDetails.hidden = true;
      registryValues = {};
      registryState.textContent = 'Unesite PIB/OIB. Podatke firme ćemo pokušati automatski da preuzmemo.';
    }
    type.addEventListener('change', function () { invalidateRegistry(); update(); });
    country.addEventListener('change', function () { invalidateRegistry(); update(); phone.setCountry(country.value); scheduleLookup(); });
    function validTax() { return new RegExp('^(?:' + fields.taxNumber.pattern + ')$').test(fields.taxNumber.value.trim()); }
    function scheduleLookup() {
      global.clearTimeout(lookupTimer);
      if (type.value === 'PL' && validTax()) lookupTimer = global.setTimeout(function () { requestCompany(false); }, 500);
    }
    function manualCompany(message) {
      registryState.className = 'efa-lead';
      fields.companyName.readOnly = false; lookup.hidden = false;
      registryState.textContent = message || 'Podaci firme nisu dostupni. Unesite naziv firme; podatke ćemo proveriti prilikom odobravanja.';
    }
    function requestCompany(force) {
      global.clearTimeout(lookupTimer); lookupTimer = null;
      if (!alive || type.value !== 'PL' || !validTax()) return;
      var selectedCountry = country.value, tax = fields.taxNumber.value.trim(), identity = selectedCountry + ':' + tax;
      if (!force && lookupKey === identity) return;
      cancelLookup(); lookupKey = identity; lookupController = new AbortController();
      var run = sequence, controller = lookupController;
      function current() { return alive && sequence === run && country.value === selectedCountry && fields.taxNumber.value.trim() === tax; }
      clearError(); registryState.className = 'efa-lead efa-loading'; registryState.textContent = 'Preuzimanje podataka firme…'; lookup.disabled = true;
      lookupDeadline = global.setTimeout(function () {
        if (!current()) return;
        cancelLookup(); lookup.disabled = false; manualCompany();
      }, 15000);
      post(base + 'register-lookup.php', { country: selectedCountry, taxNumber: tax }, controller.signal).then(function (response) {
        if (!current()) return;
        registryState.className = 'efa-lead'; var result = response.result;
        if (['found','existing'].indexOf(result.status) !== -1 && result.company && result.company.companyName) {
          ['companyName','registrationNumber','address','postalCode','city','companyEmail','companyPhone'].forEach(function (name) {
            if (typeof result.company[name] === 'string') registryValues[name] = result.company[name];
          });
          fields.companyName.value = registryValues.companyName; fields.companyName.readOnly = true;
          companyDetails.textContent = [registryValues.registrationNumber ? 'Matični broj: ' + registryValues.registrationNumber : '',
            [registryValues.address, registryValues.postalCode, registryValues.city].filter(Boolean).join(', ')].filter(Boolean).join(' · ');
          companyDetails.hidden = !companyDetails.textContent; lookup.hidden = true;
          registryState.textContent = 'Podaci firme su preuzeti. Pristup potvrđuje operater.';
        } else manualCompany(result.status === 'ambiguous' ? 'Podaci firme zahtevaju proveru podrške pre povezivanja.' : '');
      }).catch(function (e) {
        if (!current() || e.name === 'AbortError') return;
        registryState.className = 'efa-lead';
        if (e.status === 422) { fields.taxNumber.setCustomValidity(e.message); registryState.textContent = e.message; }
        else manualCompany();
      }).finally(function () { if (current()) { global.clearTimeout(lookupDeadline); lookupDeadline = null; lookup.disabled = false; lookupController = null; } });
    }
    fields.taxNumber.addEventListener('input', function () { invalidateRegistry(); scheduleLookup(); });
    fields.taxNumber.addEventListener('blur', function () { requestCompany(false); });
    lookup.addEventListener('click', function () { requestCompany(true); });
    form.addEventListener('submit', function (event) {
      event.preventDefault(); clearError(); cancelLookup();
      emailValidity();
      var phoneValue;
      try { phoneValue = phone.value(); } catch (e) { fail(e); update(); return; }
